// Cloudflare Pages entry. Pages runs one `_worker.js` in "advanced mode" and gives it the
// same `ASSETS` binding the OpenNext Worker expects, so the OpenNext server is reused as is.
// Pages only accepts a default export, so the Durable Object classes OpenNext re-exports
// (unused here: no queue, tag cache or cache purge is configured) are left out.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import worker from "../.open-next/worker.js";

const pagesWorker = {
  fetch(request, env, ctx) {
    return worker.fetch(request, env, ctx);
  },
};

export default pagesWorker;
